static UiLanguage CurrentUiLanguage() {
#ifdef TASKBAR81_TEST
    if (testLanguageOverride >= 0 && testLanguageOverride <= 4)
        return static_cast<UiLanguage>(testLanguageOverride);
#endif
    switch (PRIMARYLANGID(GetUserDefaultUILanguage())) {
        case LANG_ITALIAN:
            return UiLanguage::Italian;
        case LANG_SPANISH:
            return UiLanguage::Spanish;
        case LANG_FRENCH:
            return UiLanguage::French;
        case LANG_PORTUGUESE:
            return UiLanguage::Portuguese;
        default:
            return UiLanguage::English;
    }
}
static bool ItalianUI() {
    return CurrentUiLanguage() == UiLanguage::Italian;
}
static const wchar_t* Tr(const wchar_t* it, const wchar_t* en) {
    UiLanguage language = CurrentUiLanguage();
    if (language == UiLanguage::Italian)
        return it;
    if (language == UiLanguage::English)
        return en;
    for (const auto& entry : kUiTranslations) {
        if (wcscmp(entry.english, en))
            continue;
        if (language == UiLanguage::Spanish)
            return entry.spanish;
        if (language == UiLanguage::French)
            return entry.french;
        if (language == UiLanguage::Portuguese)
            return entry.portuguese;
        break;
    }
    return en;
}

