static std::vector<BYTE> DecodeBase64(const char* text) {
    std::vector<BYTE> bytes;
    unsigned accumulator = 0;
    int bits = 0;
    for (const unsigned char* p = reinterpret_cast<const unsigned char*>(text);
         *p; ++p) {
        unsigned v;
        if (*p >= 'A' && *p <= 'Z')
            v = *p - 'A';
        else if (*p >= 'a' && *p <= 'z')
            v = *p - 'a' + 26;
        else if (*p >= '0' && *p <= '9')
            v = *p - '0' + 52;
        else if (*p == '+')
            v = 62;
        else if (*p == '/')
            v = 63;
        else if (*p == '=')
            break;
        else
            continue;
        accumulator = (accumulator << 6) | v;
        bits += 6;
        if (bits >= 8) {
            bits -= 8;
            bytes.push_back((BYTE)((accumulator >> bits) & 255));
        }
    }
    return bytes;
}
