static void DestroyStartImage(State& state) {
    delete state.serverSpriteLarge;
    state.serverSpriteLarge = nullptr;
    if (state.serverSpriteLargeStream)
        state.serverSpriteLargeStream->Release();
    state.serverSpriteLargeStream = nullptr;
    delete state.serverSpriteSmall;
    state.serverSpriteSmall = nullptr;
    if (state.serverSpriteSmallStream)
        state.serverSpriteSmallStream->Release();
    state.serverSpriteSmallStream = nullptr;
    delete state.serverDesktopReference;
    state.serverDesktopReference = nullptr;
    if (state.serverDesktopReferenceStream)
        state.serverDesktopReferenceStream->Release();
    state.serverDesktopReferenceStream = nullptr;
    delete state.serverClassicStart;
    state.serverClassicStart = nullptr;
    if (state.serverClassicStartStream)
        state.serverClassicStartStream->Release();
    state.serverClassicStartStream = nullptr;
    delete state.win7BasicTexture;
    state.win7BasicTexture = nullptr;
    if (state.win7BasicTextureStream)
        state.win7BasicTextureStream->Release();
    state.win7BasicTextureStream = nullptr;
    for (int i = 0; i < 3; ++i) {
        delete state.peekStylerImages[i];
        state.peekStylerImages[i] = nullptr;
        if (state.peekStylerStreams[i])
            state.peekStylerStreams[i]->Release();
        state.peekStylerStreams[i] = nullptr;
    }
    delete state.taskStateSprite;
    state.taskStateSprite = nullptr;
    if (state.taskStateStream)
        state.taskStateStream->Release();
    state.taskStateStream = nullptr;
    delete state.win7Beta7000StartImage;
    state.win7Beta7000StartImage = nullptr;
    if (state.win7Beta7000StartStream)
        state.win7Beta7000StartStream->Release();
    state.win7Beta7000StartStream = nullptr;
    delete state.win7StartImage;
    state.win7StartImage = nullptr;
    if (state.win7StartStream)
        state.win7StartStream->Release();
    state.win7StartStream = nullptr;
    for (auto& image : state.tintBeta) {
        delete image;
        image = nullptr;
    }
    for (size_t i = 0; i < std::size(state.betaTexture); ++i) {
        delete state.betaTexture[i];
        state.betaTexture[i] = nullptr;
        if (state.betaTextureStream[i])
            state.betaTextureStream[i]->Release();
        state.betaTextureStream[i] = nullptr;
    }
    delete state.betaStartImage;
    state.betaStartImage = nullptr;
    if (state.betaStartStream)
        state.betaStartStream->Release();
    state.betaStartStream = nullptr;
    delete state.startImage;
    state.startImage = nullptr;
    if (state.startStream)
        state.startStream->Release();
    state.startStream = nullptr;
}
static bool LoadStartImage(State& state) {
    const auto bytes = DecodeBase64(kStartPngBase64);
    if (bytes.empty() || bytes.size() > 0xFFFFFFFFu)
        return false;
    state.startStream = SHCreateMemStream(bytes.data(), (UINT)bytes.size());
    if (!state.startStream)
        return false;
    state.startImage = Gdiplus::Image::FromStream(state.startStream, FALSE);
    if (!state.startImage || state.startImage->GetLastStatus() != Ok ||
        state.startImage->GetWidth() != 50 ||
        state.startImage->GetHeight() != 123) {
        DestroyStartImage(state);
        return false;
    }
    return true;
}
static bool LoadWin7StartImage(State& state) {
    const auto bytes = DecodeBase64(kWin7StartPngBase64);
    if (bytes.empty() || bytes.size() > 0xFFFFFFFFu)
        return false;
    state.win7StartStream = SHCreateMemStream(bytes.data(), (UINT)bytes.size());
    if (!state.win7StartStream)
        return false;
    state.win7StartImage = Image::FromStream(state.win7StartStream, FALSE);
    if (!state.win7StartImage || state.win7StartImage->GetLastStatus() != Ok ||
        state.win7StartImage->GetWidth() != 54 ||
        state.win7StartImage->GetHeight() != 162) {
        delete state.win7StartImage;
        state.win7StartImage = nullptr;
        state.win7StartStream->Release();
        state.win7StartStream = nullptr;
        return false;
    }
    return true;
}
